"""Independent slow reference implementation for testing."""
from fractions import Fraction
from itertools import product as iproduct

G = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
INV = (2, 1, 0)


def canon(a, b):
    return (a, b) if a < b else (b, a)


def normalize(path, ixps):
    out = []
    for x in path:
        if x in ixps:
            continue
        if out and out[-1] == x:
            continue
        out.append(x)
    return out


def ref_peel(agg):
    paths = dict(agg)
    rounds = {}
    r = 0
    while True:
        r += 1
        allu = {}
        present = set()
        for p in paths:
            first, last = p[0], p[-1]
            for i in range(len(p) - 1):
                key = canon(p[i], p[i + 1])
                present.add(key)
                u, v = key
                if key not in allu:
                    allu[key] = [True, True]
                if not (first == u or last == u):
                    allu[key][0] = False
                if not (first == v or last == v):
                    allu[key][1] = False
        marked = set()
        for k in present:
            if allu[k][0] or allu[k][1]:
                marked.add(k)
        if not marked:
            break
        for k in marked:
            rounds[k] = r
        newpaths = {}
        for p, c in paths.items():
            fl = canon(p[0], p[1])
            ll = canon(p[-2], p[-1])
            s = 1 if fl in marked else 0
            e = len(p) - 1 if ll in marked else len(p)
            q = p[s:e]
            if len(q) >= 2:
                newpaths[q] = newpaths.get(q, 0) + c
        paths = newpaths
    return paths, rounds


def ref_occurrences(final):
    occs = {}
    for p, cnt in final.items():
        n = len(p)
        for i in range(n - 1):
            a, b = p[i], p[i + 1]
            u, v = canon(a, b)
            if a == u:
                o = p
                oi = i
            else:
                o = p[::-1]
                oi = n - 2 - i
            if oi == 0:
                L = ('c', 0)
            else:
                x = o[oi - 1]
                L = ('v', canon(x, u), x > u)
            if oi + 2 == n:
                R = ('c', 2)
            else:
                y = o[oi + 2]
                R = ('v', canon(v, y), v > y)
            occs.setdefault((u, v), []).append((cnt, L, R))
    return occs


def scope_graph(occs, core_links):
    adj = {l: set() for l in core_links}
    for l, lst in occs.items():
        for (cnt, L, R) in lst:
            for spec in (L, R):
                if spec[0] == 'v':
                    adj[l].add(spec[1])
                    adj[spec[1]].add(l)
    return adj


def find_order(adj):
    """Min-degree elimination; returns order or None if width > 4."""
    cur = {k: set(v) for k, v in adj.items()}
    order = []
    while cur:
        best = None
        bestdeg = None
        for k in sorted(cur):
            d = len(cur[k])
            if bestdeg is None or d < bestdeg:
                best = k
                bestdeg = d
        if bestdeg > 4:
            return None
        k = best
        nbrs = cur.pop(k)
        for a in nbrs:
            cur[a].discard(k)
        for a in nbrs:
            for b in nbrs:
                if a != b:
                    cur[a].add(b)
        order.append(k)
    return order


def ref_infer(occs, core_links):
    links = sorted(core_links)
    Z = 0
    marg = {l: [0, 0, 0] for l in links}
    for vals in iproduct(range(3), repeat=len(links)):
        assign = dict(zip(links, vals))
        w = 1
        for l in links:
            val = 0
            for (cnt, L, R) in occs.get(l, []):
                if L[0] == 'c':
                    lv = L[1]
                else:
                    lv = assign[L[1]] if not L[2] else INV[assign[L[1]]]
                if R[0] == 'c':
                    rv = R[1]
                else:
                    rv = assign[R[1]] if not R[2] else INV[assign[R[1]]]
                if G[lv][rv] == assign[l]:
                    val += cnt
            w *= val
            if w == 0:
                break
        if w:
            Z += w
            for l in links:
                marg[l][assign[l]] += w
    return Z, marg


def ref_solve(doc):
    ixps = set(doc['ixps'])
    agg = {}
    for rec in doc['rib']:
        p = normalize(rec['path'], ixps)
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        key = tuple(p)
        agg[key] = agg.get(key, 0) + rec['count']
    orig_links = set()
    for p in agg:
        for i in range(len(p) - 1):
            orig_links.add(canon(p[i], p[i + 1]))
    final, rounds = ref_peel(agg)
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(canon(p[i], p[i + 1]))
    priors = {}
    for rec in doc['priors']:
        u, v = rec['link']
        w = rec['weights']
        s = sum(w)
        priors[canon(u, v)] = tuple(Fraction(x, s) for x in
                                    (w if u < v else (w[2], w[1], w[0])))
    declared = {}
    for rec in doc['declared']:
        u, v = rec['link']
        code = {'c2p': 0, 'p2p': 1, 'p2c': 2}[rec['rel']]
        if u > v:
            code = INV[code]
        declared[canon(u, v)] = tuple(Fraction(int(code == t)) for t in range(3))
    occs = ref_occurrences(final)
    Z, marg = ref_infer(occs, core)
    if Z == 0:
        return {'error': 'zero-partition'}
    margfrac = {l: tuple(Fraction(x, Z) for x in marg[l]) for l in core}
    links_out = []
    for l in sorted(orig_links):
        if l in core:
            links_out.append({'link': list(l), 'round': 0,
                              'prob': [float(x) for x in margfrac[l]]})
        else:
            links_out.append({'link': list(l), 'round': rounds[l],
                              'prob': [float(x) for x in priors.get(
                                  l, (Fraction(1, 3),) * 3)]})

    def lookup(a, b):
        key = canon(a, b)
        if key in declared:
            vec = declared[key]
        elif key in margfrac:
            vec = margfrac[key]
        elif key in priors:
            vec = priors[key]
        else:
            vec = (Fraction(1, 3),) * 3
        if a > b:
            vec = (vec[2], vec[1], vec[0])
        return vec

    qs = []
    for rec in doc['queries']:
        p = normalize(rec['path'], ixps)
        out = {'id': rec['id'], 'path': p, 'status': 'ok', 'score': None,
               'full': None, 'witness': None, 'leaked': None}
        if len(set(p)) != len(p):
            out['status'] = 'loop'
            qs.append(out)
            continue
        if len(p) <= 2:
            out['score'] = 1.0
            out['full'] = 1.0
            out['leaked'] = False
            qs.append(out)
            continue
        vecs = [lookup(p[i], p[i + 1]) for i in range(len(p) - 1)]
        triples = []
        for i in range(len(vecs) - 1):
            U = vecs[i][0]
            D = vecs[i + 1][2]
            triples.append(U + D - U * D)
        best = None
        wit = None
        for i, t in enumerate(triples):
            if best is None or t < best:
                best = t
                wit = i
        out['score'] = float(best)
        out['witness'] = wit
        a, b = rec['threshold']
        out['leaked'] = bool(best < Fraction(a, b))
        # full: enumerate all sequences
        total = Fraction(0)
        k = len(vecs)
        for seq in iproduct(range(3), repeat=k):
            # c2p* p2p p2c*  or  c2p* p2c*
            seen_p2p = seq.count(1)
            ok = False
            if seen_p2p == 0:
                ok = all(x in (0, 2) for x in seq) and _is_up_down(seq)
            elif seen_p2p == 1:
                ok = _is_up_down(seq)
            if ok:
                w = Fraction(1)
                for i, t in enumerate(seq):
                    w *= vecs[i][t]
                total += w
        out['full'] = float(total)
        qs.append(out)
    return {'version': 1, 'links': links_out, 'queries': qs}


def _is_up_down(seq):
    # c2p^a (p2p)? p2c^c  with at most one p2p
    state = 0
    for x in seq:
        if state == 0:
            if x == 0:
                pass
            elif x == 1:
                state = 1
            else:
                state = 2
        elif state == 1:
            if x == 1:
                return False
            elif x == 2:
                state = 2
            else:
                return False
        else:
            if x != 2:
                return False
    return True
